public import Foundation

/// The repository's test files, which aren't checked in: `TestData/SET`, made by `Tools/test-data fetch SET`
/// (downloaded and checked, or generated by a checked-in script).
public enum TestData {
    /// The repository's `TestData` directory (found from this file's path: every package is in the repository).
    public static let root = URL(filePath: #filePath)
        .deletingLastPathComponent() // BytesTestSupport
        .deletingLastPathComponent() // Sources
        .deletingLastPathComponent() // Bytes
        .deletingLastPathComponent() // the repository
        .appending(path: "TestData")

    /// A test file that hasn't been fetched or generated.
    public struct Missing: Error, CustomStringConvertible {
        /// The set it belongs to.
        public let set: String
        /// Its name in the set.
        public let name: String

        /// A missing file.
        ///
        /// - Parameters:
        ///   - set: The set it belongs to.
        ///   - name: Its name in the set.
        public init(set: String, name: String) {
            self.set = set
            self.name = name
        }

        /// Names the file and the command that makes it.
        public var description: String { "\(set)/\(name) is missing: run Tools/test-data fetch \(set)" }
    }

    /// The directory of `set`, whether it's there or not.
    ///
    /// - Parameter set: The set's name, as `Tools/test-data list` prints it.
    /// - Returns: `TestData/SET`.
    public static func directory(set: String) -> URL {
        root.appending(path: set)
    }

    /// The file `name` of `set`.
    ///
    /// - Parameters:
    ///   - set: The set's name.
    ///   - name: The file's path in the set.
    /// - Returns: Its URL.
    /// - Throws: ``Missing`` if it isn't there.
    public static func file(set: String, name: String) throws(Missing) -> URL {
        let url = directory(set: set).appending(path: name)
        guard FileManager.default.fileExists(atPath: url.path(percentEncoded: false)) else {
            throw Missing(set: set, name: name)
        }
        return url
    }
}

/// The compression corpus `Tools/corpus fetch` downloads (Silesia, web assets, …), cached outside the repository.
public enum Corpus {
    /// `EXPERIMENTS_CORPUS` if it's set, otherwise `~/Library/Caches/Experiments/corpus`.
    public static var root: URL {
        if let path = ProcessInfo.processInfo.environment["EXPERIMENTS_CORPUS"] { return URL(filePath: path) }
        return FileManager.default.homeDirectoryForCurrentUser.appending(path: "Library/Caches/Experiments/corpus")
    }

    /// The corpus file at `path`, or `nil` if the corpus doesn't have it.
    ///
    /// - Parameter path: Relative to ``root`` (`"silesia/dickens"`).
    /// - Returns: Its URL.
    public static func file(_ path: String) -> URL? {
        let url = root.appending(path: path)
        return FileManager.default.fileExists(atPath: url.path(percentEncoded: false)) ? url : nil
    }
}
